import { GoogleGenAI } from "@google/genai";
import { GeneratedImage, GenerationConfig, ReferenceImage } from "../types";

export const generateConsistentImage = async (
  references: ReferenceImage[],
  prompt: string,
  config: GenerationConfig
): Promise<GeneratedImage> => {
  // Ensure we have a fresh instance with the latest selected key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    Você é um gerador de imagens especializado em consistência de identidade ultra-realista.
    Sua tarefa é gerar uma nova imagem baseada nas imagens de referência fornecidas e no prompt do usuário.

    INSTRUÇÕES CRÍTICAS:
    1. Analise TODAS as imagens de referência fornecidas para extrair a identidade facial completa (olhos, nariz, boca, estrutura óssea, cabelo).
    2. A pessoa na nova imagem deve ser INDISTINGUÍVEL da pessoa nas referências.
    3. Mantenha etnia, idade aproximada e biotipo.
    4. Insira esta pessoa no novo contexto solicitado pelo usuário de forma natural.
    5. O estilo deve ser fotorealista, cinematográfico e de altíssima qualidade.
  `;

  // Construct multimodal prompt parts: All Images + Text instructions
  const imageParts = references.map(ref => ({
    inlineData: {
      data: ref.base64,
      mimeType: ref.mimeType,
    },
  }));

  const textPart = {
    text: `Baseado nas imagens de referência fornecidas, gere uma nova imagem com a seguinte descrição: "${prompt}". 
    Mantenha a identidade facial e a aparência física da pessoa consistentemente. Use iluminação profissional.`,
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [...imageParts, textPart],
      },
      config: {
        systemInstruction: systemInstruction,
        imageConfig: {
          aspectRatio: config.aspectRatio,
          imageSize: config.imageSize,
        },
      },
    });

    let finalImageUrl = '';

    if (response.candidates && response.candidates[0].content && response.candidates[0].content.parts) {
       for (const part of response.candidates[0].content.parts) {
         if (part.inlineData) {
           const base64Data = part.inlineData.data;
           finalImageUrl = `data:image/png;base64,${base64Data}`;
           break;
         }
       }
    }

    if (!finalImageUrl) {
      throw new Error("O modelo não gerou uma imagem. Pode ser devido a restrições de segurança ou complexidade do prompt.");
    }

    return {
      id: crypto.randomUUID(),
      url: finalImageUrl,
      prompt: prompt,
      timestamp: Date.now(),
    };

  } catch (error) {
    console.error("Erro na geração:", error);
    throw error;
  }
};

export const checkApiKeyStatus = async (): Promise<boolean> => {
  if (window.aistudio && window.aistudio.hasSelectedApiKey) {
    return await window.aistudio.hasSelectedApiKey();
  }
  return false;
};

export const promptApiKeySelection = async (): Promise<void> => {
  if (window.aistudio && window.aistudio.openSelectKey) {
    await window.aistudio.openSelectKey();
  }
};

import React, { useRef } from 'react';
import { ReferenceImage } from '../types';
import { UploadIcon, TrashIcon } from './Icons';

interface ReferenceUploaderProps {
  references: ReferenceImage[];
  onImagesUpdate: (images: ReferenceImage[]) => void;
}

const MultiReferenceUploader: React.FC<ReferenceUploaderProps> = ({ references, onImagesUpdate }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const remainingSlots = 3 - references.length;
    const filesToProcess = Array.from(files).slice(0, remainingSlots);

    const newImages: ReferenceImage[] = [];

    for (const file of filesToProcess) {
      const base64Data = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = (e) => resolve(e.target?.result as string);
        reader.readAsDataURL(file);
      });

      const match = base64Data.match(/^data:(.+);base64,(.*)$/);
      if (match) {
        newImages.push({
          file,
          previewUrl: base64Data,
          mimeType: match[1],
          base64: match[2],
        });
      }
    }

    onImagesUpdate([...references, ...newImages]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeImage = (index: number) => {
    const updated = [...references];
    updated.splice(index, 1);
    onImagesUpdate(updated);
  };

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-3 gap-3">
        {[0, 1, 2].map((index) => {
          const image = references[index];
          return (
            <div 
              key={index} 
              className={`relative aspect-square rounded-xl border-2 overflow-hidden transition-all ${
                image 
                ? 'border-slate-700 bg-slate-800' 
                : 'border-dashed border-slate-800 bg-slate-900/50 hover:border-cyan-500/50 cursor-pointer'
              }`}
              onClick={() => !image && fileInputRef.current?.click()}
            >
              {image ? (
                <>
                  <img 
                    src={image.previewUrl} 
                    alt={`Ref ${index + 1}`} 
                    className="w-full h-full object-cover"
                  />
                  <button 
                    onClick={(e) => { e.stopPropagation(); removeImage(index); }}
                    className="absolute top-1 right-1 p-1 bg-red-500/80 hover:bg-red-600 text-white rounded-full transition-colors backdrop-blur-sm"
                  >
                    <TrashIcon className="w-3.5 h-3.5" />
                  </button>
                </>
              ) : (
                <div className="w-full h-full flex items-center justify-center">
                  <UploadIcon className="w-6 h-6 text-slate-700" />
                </div>
              )}
            </div>
          );
        })}
      </div>

      {references.length < 3 && (
        <p className="text-[10px] text-center text-slate-500 uppercase tracking-tighter">
          Adicione até {3 - references.length} mais fotos para maior precisão
        </p>
      )}

      <input 
        ref={fileInputRef}
        type="file" 
        multiple
        accept="image/*" 
        className="hidden"
        onChange={handleFileChange}
      />
    </div>
  );
};

export default MultiReferenceUploader;

import React, { useState, useEffect } from 'react';
import { GeneratedImage, ReferenceImage, GenerationConfig } from './types';
import { generateConsistentImage, checkApiKeyStatus, promptApiKeySelection } from './services/geminiService';
import MultiReferenceUploader from './components/ReferenceUploader';
import { WandIcon, DownloadIcon, LoaderIcon, AlertIcon, ImageIcon } from './components/Icons';

const App: React.FC = () => {
  const [hasApiKey, setHasApiKey] = useState<boolean>(false);
  const [referenceImages, setReferenceImages] = useState<ReferenceImage[]>([]);
  const [prompt, setPrompt] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [config, setConfig] = useState<GenerationConfig>({
    aspectRatio: '1:1',
    imageSize: '1K',
  });

  useEffect(() => {
    checkApiKeyStatus().then(setHasApiKey);
  }, []);

  const handleApiKeyConnect = async () => {
    try {
      await promptApiKeySelection();
      setHasApiKey(true); 
    } catch (e) {
      console.error("Failed to connect API key", e);
      setError("Falha ao conectar chave de API. Tente novamente.");
    }
  };

  const handleGenerate = async () => {
    if (referenceImages.length === 0) {
      setError("Por favor, envie ao menos uma imagem de referência.");
      return;
    }
    if (!prompt.trim()) {
      setError("Por favor, descreva a nova situação.");
      return;
    }

    setIsGenerating(true);
    setError(null);

    try {
      const result = await generateConsistentImage(referenceImages, prompt, config);
      setGeneratedImages(prev => [result, ...prev]);
    } catch (err: any) {
      setError(err.message || "Erro na geração. Tente um prompt diferente.");
      if (err.message && err.message.includes('API key')) setHasApiKey(false);
    } finally {
      setIsGenerating(false);
    }
  };

  const downloadImage = (url: string, id: string) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `personagen-${id}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (!hasApiKey) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4">
        <div className="max-w-md w-full bg-slate-900 border border-slate-800 rounded-2xl p-8 text-center shadow-2xl">
          <div className="w-16 h-16 bg-cyan-500/20 rounded-full flex items-center justify-center mx-auto mb-6">
            <WandIcon className="w-8 h-8 text-cyan-400" />
          </div>
          <h1 className="text-3xl font-bold text-white mb-3">PersonaGen</h1>
          <p className="text-slate-400 mb-8">
            Combine múltiplas fotos para criar personagens com identidade consistente. Requer conta Google Cloud (Gemini 3 Pro).
          </p>
          <button
            onClick={handleApiKeyConnect}
            className="w-full py-3 px-4 bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 text-white font-semibold rounded-lg transition-all transform active:scale-95 shadow-lg"
          >
            Conectar Google Cloud
          </button>
          <div className="mt-6 text-xs text-slate-600 underline">
            <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noreferrer">
              Saiba mais sobre o faturamento
            </a>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100">
      <header className="sticky top-0 z-20 backdrop-blur-md bg-slate-950/80 border-b border-slate-800">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <WandIcon className="w-6 h-6 text-cyan-400" />
            <span className="font-bold text-xl">PersonaGen <span className="text-[10px] text-cyan-500 ml-1 px-1.5 py-0.5 border border-cyan-500/30 rounded uppercase">Multi-Ref</span></span>
          </div>
          <div className="flex items-center gap-4 text-xs text-slate-500">
             <span>Gemini 3 Pro + Identidade</span>
             <div className="w-2 h-2 rounded-full bg-green-500"></div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-4 space-y-6">
          <section className="bg-slate-900/50 border border-slate-800 rounded-2xl p-6">
            <h2 className="text-sm font-bold mb-4 uppercase tracking-widest text-slate-400 flex items-center gap-2">
              <span className="w-5 h-5 rounded-full bg-cyan-500 text-slate-950 flex items-center justify-center text-[10px]">1</span>
              Referências ({referenceImages.length}/3)
            </h2>
            <MultiReferenceUploader 
              references={referenceImages}
              onImagesUpdate={setReferenceImages}
            />
          </section>

          <section className="bg-slate-900/50 border border-slate-800 rounded-2xl p-6 space-y-4">
            <h2 className="text-sm font-bold uppercase tracking-widest text-slate-400 flex items-center gap-2">
              <span className="w-5 h-5 rounded-full bg-cyan-500 text-slate-950 flex items-center justify-center text-[10px]">2</span>
              Novo Cenário
            </h2>

            <textarea 
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="Ex: vestindo traje de astronauta na superfície de Marte, estilo realista..."
              className="w-full bg-slate-950 border border-slate-800 rounded-lg p-3 text-sm focus:ring-1 focus:ring-cyan-500 outline-none transition-all h-28 resize-none"
            />

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-[10px] text-slate-500 uppercase block mb-1">Formato</label>
                <select 
                  value={config.aspectRatio}
                  onChange={(e) => setConfig({...config, aspectRatio: e.target.value as any})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-xs outline-none"
                >
                  <option value="1:1">1:1</option>
                  <option value="16:9">16:9</option>
                  <option value="9:16">9:16</option>
                  <option value="3:4">3:4</option>
                </select>
              </div>
              <div className="opacity-50">
                <label className="text-[10px] text-slate-500 uppercase block mb-1">Qualidade</label>
                <div className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-xs">Premium</div>
              </div>
            </div>

            {error && (
              <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-lg flex items-start gap-2">
                <AlertIcon className="w-4 h-4 text-red-500 mt-0.5" />
                <p className="text-[11px] text-red-200">{error}</p>
              </div>
            )}

            <button
              onClick={handleGenerate}
              disabled={isGenerating || referenceImages.length === 0 || !prompt}
              className="w-full py-4 bg-cyan-600 hover:bg-cyan-500 disabled:opacity-30 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-all flex items-center justify-center gap-2"
            >
              {isGenerating ? <><LoaderIcon className="w-5 h-5 animate-spin" /> Gerando...</> : <><WandIcon className="w-5 h-5" /> Criar Imagem</>}
            </button>
          </section>
        </div>

        <div className="lg:col-span-8">
           <div className="bg-slate-900/20 border border-slate-800 rounded-2xl p-6 min-h-[600px]">
              <div className="flex items-center justify-between mb-8">
                <h2 className="text-xl font-bold flex items-center gap-2">
                  <ImageIcon className="text-cyan-500" />
                  Galeria de Criações
                </h2>
                <span className="text-xs font-mono text-slate-600">{generatedImages.length} ITEMS</span>
              </div>

              {generatedImages.length === 0 ? (
                <div className="h-[450px] flex flex-col items-center justify-center text-slate-700 border border-dashed border-slate-800 rounded-2xl">
                  <p className="text-sm">Combine suas referências para começar.</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  {generatedImages.map((img) => (
                    <div key={img.id} className="group bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden shadow-2xl transition-all hover:border-cyan-500/40">
                      <div className="aspect-square relative overflow-hidden bg-slate-950">
                        <img src={img.url} className="w-full h-full object-cover transition-transform group-hover:scale-105" />
                        <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => downloadImage(img.url, img.id)} className="p-2 bg-white text-slate-950 rounded-full shadow-lg hover:bg-cyan-400">
                            <DownloadIcon className="w-5 h-5" />
                          </button>
                        </div>
                      </div>
                      <div className="p-4 bg-gradient-to-b from-slate-900 to-slate-950">
                        <p className="text-xs text-slate-300 italic mb-2">"{img.prompt}"</p>
                        <p className="text-[10px] text-slate-600 uppercase font-bold tracking-tighter">Gerado em {new Date(img.timestamp).toLocaleTimeString()}</p>
                      </div>
                    </div>
                  ))}
                </div>
              )}
           </div>
        </div>
      </main>
    </div>
  );
};

export default App;

export interface GeneratedImage {
  id: string;
  url: string;
  prompt: string;
  timestamp: number;
}

export interface GenerationConfig {
  aspectRatio: '1:1' | '3:4' | '4:3' | '16:9' | '9:16';
  imageSize: '1K' | '2K'; // Gemini 3 Pro supports these
}

export interface ReferenceImage {
  file: File;
  previewUrl: string;
  base64: string; // Plain base64 string without data prefix
  mimeType: string;
}

// Global interface for AI Studio auth
